import{_ as r,o,c as t,ag as a}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Manage a published Form from HCL","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md"}'),s={name:"docs/getting-started.md"};function i(n,e,d,c,h,l){return o(),t("div",null,[...e[0]||(e[0]=[a(`<p>English: <a href="/ja/docs/getting-started.html">日本語</a></p><h1 id="manage-a-published-form-from-hcl" tabindex="-1">Manage a published Form from HCL <a class="header-anchor" href="#manage-a-published-form-from-hcl" aria-label="Permalink to &quot;Manage a published Form from HCL&quot;">​</a></h1><p>This walkthrough uses Registry-published Provider 4.1.0 and the Host API v1 contract. Provider 5.0.0 is the current source target, but its release ledger still marks it candidate-only; it has a separate Host API v2 configuration and fresh-install state model. See the <a href="/docs/provider-host-api-v2-source.html">Provider 5 consumer reference</a> for that path. Provider 4 state is not automatically migrated to Provider 5.</p><p>This guide introduces a small Terraform/OpenTofu module with one Random Provider resource and one Takoform resource. The example is <a href="/examples/getting-started/main.tf"><code>examples/getting-started/main.tf</code></a>.</p><p>This Provider is for HCL authors who want to manage an explicit set of published Takoform Forms. It is an ordinary peer of AWS, Cloudflare, and other Providers: you declare each source in <code>required_providers</code>, then OpenTofu or Terraform resolves the dependency graph. This Provider does not create a Host, choose its backend, or provide a catalog of every Form.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Have these ready before planning:</p><ul><li>Terraform or OpenTofu and a compatible Takoform Host.</li><li>The Host&#39;s endpoint, exact Space ID, and (if that Host requires it) a bearer token from the Host operator. The Host must support the exact FormRef used by each resource.</li><li>The Random Provider needs no cloud credentials. Applying the Takoform resource changes the selected Host.</li></ul><p>The Takoform endpoint and Space are supplied by your selected Host; there is no default Host or Space. Keep a bearer token out of HCL and variable files. If needed, provide it to the process as <code>TAKOFORM_TOKEN</code> through your normal secret-injection mechanism. <code>TAKOFORM_ENDPOINT</code> and <code>TAKOFORM_SPACE</code> are also supported when you configure the Provider through its environment variables.</p><h2 id="declare-both-providers" tabindex="-1">Declare both Providers <a class="header-anchor" href="#declare-both-providers" aria-label="Permalink to &quot;Declare both Providers&quot;">​</a></h2><p>Use the checked-in <a href="/examples/getting-started/main.tf">example module</a>. It declares <code>registry.terraform.io/tako0614/takoform</code> beside the <code>registry.terraform.io/hashicorp/random</code> Provider. The Random resource provides a generated suffix for the <code>takoform_edge_kv_namespace</code> name through a normal HCL reference. The Random Provider has no cloud account to configure; the Takoform Provider alone manages the namespaced resource on the selected Host. For a cloud-provider composition example, see the existing <a href="/examples/native-provider-composition/main.tf">AWS S3 example</a>.</p><p>From the example directory, check formatting, initialize the module, and validate it. After supplying the required inputs and credentials, review the plan before applying:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd examples/getting-started</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu fmt -check</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu init</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu validate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu plan</span></span></code></pre></div><p>Use <code>terraform</code> in place of <code>tofu</code> when working with Terraform. Supply these two non-secret inputs through your usual variable mechanism: Host endpoint and Space ID. Reviewing the plan is important because applying it creates a namespace on the selected Host. Apply only after confirming the target and the planned changes.</p><p>This resource maps to the published <a href="https://edge.forms.takoform.com/forms/EdgeKVNamespace/0.1.0/" target="_blank" rel="noreferrer">EdgeKVNamespace Form at definition 0.1.0</a>. A compatible Host must advertise support for that exact FormRef before it can apply the resource. The separate <a href="https://takoform.com/en/host-api/" target="_blank" rel="noreferrer">Host API documentation</a> describes the provider-neutral Host contract; it does not supply a hosted endpoint or credentials.</p><h2 id="provider-versions-and-form-identities" tabindex="-1">Provider versions and Form identities <a class="header-anchor" href="#provider-versions-and-form-identities" aria-label="Permalink to &quot;Provider versions and Form identities&quot;">​</a></h2><p>In the example, <code>version = &quot;~&gt; 4.0&quot;</code> constrains the Provider package to the 4.x line; Provider 4.1.0 is the published release documented here. For a fixed selection, use <code>version = &quot;= 4.1.0&quot;</code>. <code>tofu init</code> records the selected Provider package and checksums in <code>.terraform.lock.hcl</code>; commit that lock file with a real module. This version constraint is <strong>not</strong> a Form pin. The Provider release maps each resource type to an exact FormRef; state records the API version, kind, definition version, and schema digest used by that resource. For this example, the mapping is <code>edge.forms.takoform.com/EdgeKVNamespace</code>, definition <code>0.1.0</code>. See the <a href="/docs/resources/edge_kv_namespace.html#exact-formref">resource reference</a> for the complete identity and state behavior.</p><h2 id="sensitive-workerversion-inputs" tabindex="-1">Sensitive WorkerVersion inputs <a class="header-anchor" href="#sensitive-workerversion-inputs" aria-label="Permalink to &quot;Sensitive WorkerVersion inputs&quot;">​</a></h2><p><code>TAKOFORM_TOKEN</code> is a credential for the Host API. It is different from application secrets that Worker code needs at runtime. A <a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code></a> declares only the names of required sensitive values in <code>required_sensitive_vars</code>. The values are delivered through the Provider&#39;s Apply-only <code>runtime_inputs</code> map using an ephemeral root-variable path supported by the execution runner; the values do not enter a saved plan or Terraform/OpenTofu state. Do not put these values in HCL literals, <code>vars_json</code>, ordinary <code>.tfvars</code> files, command arguments, or ambient variables. Read <a href="/docs/resources/worker_version.html#run-scoped-sensitive-inputs">Run-scoped sensitive inputs</a> before configuring this path: the nonce, Provider instance, and Apply-time map must match, and a runner that does not implement ephemeral delivery cannot apply those inputs.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Browse the <a href="/docs/reference.html#resource-reference">complete resource reference</a> and <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/forms/README.md" target="_blank" rel="noreferrer">Provider-to-Form mapping inventory</a>.</li><li>Read the <a href="https://takoform.com/en/host-api/" target="_blank" rel="noreferrer">Takoform Host API</a> separately when you need the provider-neutral Host contract.</li><li>Before upgrading Provider 3, read the <a href="./../release/migrations/v3-to-v4.html">v3-to-v4 migration guide</a>.</li></ul>`,21)])])}const u=r(s,[["render",i]]);export{m as __pageData,u as default};
